args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?bdate WHERE {
  VALUES ?film { dbr:Five_Red_Tulips dbr:Laughing_at_Death }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bdate1. }
  OPTIONAL { ?director dbp:birthDate ?bdate2. }
  BIND(COALESCE(?bdate1, ?bdate2) AS ?bdateRaw)
  FILTER(bound(?bdateRaw))
  BIND(xsd:date(?bdateRaw) AS ?bdate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
}
ORDER BY DESC(?bdate)
LIMIT 1

